/**
 * api.js
 *
 * PRIMARY:  iTunes Search API — direct from browser (native CORS, no proxy)
 * BONUS:    TheAudioDB — artist bio/art via /api/audiodb serverless function
 *           Works on Vercel (api/audiodb.js) AND locally (proxy.js on port 3001)
 */

// ── iTunes (direct, native CORS) ──────────────────────────────────────────────
export async function itunesSearchTracks(artist, limit = 50) {
  const url = `https://itunes.apple.com/search?${new URLSearchParams({
    term: artist, entity: 'song', limit, sort: 'popular',
  })}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`iTunes ${res.status}`);
  return res.json();
}

export async function itunesSearchAlbums(artist, limit = 20) {
  const url = `https://itunes.apple.com/search?${new URLSearchParams({
    term: artist, entity: 'album', limit,
  })}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`iTunes albums ${res.status}`);
  return res.json();
}

// ── TheAudioDB via /api/audiodb (works on Vercel + local) ────────────────────
async function adbFetch(path, params = {}) {
  try {
    const qs = new URLSearchParams({ path, ...params }).toString();
    const res = await fetch(`/api/audiodb?${qs}`, {
      signal: AbortSignal.timeout(5000),
    });
    if (!res.ok) return null;
    return res.json();
  } catch {
    return null; // graceful fallback — iTunes covers everything
  }
}

export const adbArtistInfo = (s) => adbFetch('search.php', { s });
